function esc($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
function me(){return $_SESSION['pengguna']??null;}
function login_required(){if(!me()){header('Location: ?halaman=masuk');exit;}}
function role($r){return me() && me()['peran']===$r;}
function value($j,$k){return esc($j[$k]??'');}
function dipilih($data,$kolom,$nilai){return in_array($nilai,array_map('trim',explode(',',(string)($data[$kolom]??''))),true);}
function bulan_indonesia($tanggal){$nama=['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];$waktu=strtotime($tanggal);return $nama[(int)date('n',$waktu)-1].' '.date('Y',$waktu);}
function tanggal_indonesia($tanggal){$nama=['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];$waktu=strtotime($tanggal);return date('d',$waktu).' '.$nama[(int)date('n',$waktu)-1].' '.date('Y',$waktu);}
