  if($aksi==='paraf'){login_required();$tgl=$_POST['tanggal'];if(role('murid') && $tgl>date('Y-m-d')){header('Location: ?halaman=jurnal&tanggal='.$tgl.'&error=masa_depan');exit;}$cek=$db->prepare('SELECT status_persetujuan FROM jurnal_harian WHERE id_murid=? AND tanggal=?');$cek->execute([me()['id'],$tgl]);if(role('murid') && (($cek->fetch(PDO::FETCH_ASSOC)['status_persetujuan']??'')==='Disetujui')){header('Location: ?halaman=jurnal&tanggal='.$tgl.'&error=disetujui');exit;}$db->prepare("UPDATE jurnal_harian SET paraf_orang_tua=?, diperbarui_pada=? WHERE id_murid=? AND tanggal=?")->execute([date('d/m/Y H:i'),date('c'),me()['id'],$tgl]);header('Location: ?halaman=jurnal&tanggal='.$tgl.'&paraf=1');exit;}
