></option><?php endforeach;?></select><button class="bg-sky-600 text-white rounded-lg px-3 py-2">Filter</button></form><?php endif;?><button onclick="window.print()" class="bg-rose-500 text-white rounded-lg px-4 py-2 font-bold">🖨 Cetak PDF</button></div><section class="rekap-cetak card rounded-2xl p-3 sm:p-6 print-area"><div class="text-center mb-4"><div class="rekap-judul">Rekapitulasi Pemantauan dan Penilaian Tujuh<br>Kebiasaan Anak Indonesia Hebat Semester</div></div><div class="text-center mb-3">Semester : <span class="garis-data"><?=ucfirst($sem)?></span></div><div class="leading-7">Sekolah : <span class="garis-data"><?=esc($namaSekolah)?></span><br>Nama : <span class="garis-data"><?=esc($profilRekap['nama'])?></span><br>Kelas : <span class="garis-data" style="min-width:150px"><?=esc($profilRekap['kelas'] ?: 'Kelas III')?></span></div><div class="grid grid-cols-3 text-sm leading-6 my-3"><?php foreach($namaBulan as $i=>$nm):?><div><?=$nm?> : <?=in_array(str_pad((string)($i+1),2,'0',STR_PAD_LEFT),$bulan)?'✓':''?></div><?php endforeach;?></div><table class="tabel-rekap"><thead><tr><th rowspan="2" class="w-12">No.</th><th rowspan="2">Tujuh Kebiasaan Anak<br>Indonesia Hebat</th><th colspan="2">Penerapan 7 Kebiasaan<br>Anak Indonesia Hebat</th></tr><tr><th>Belum Terbiasa</th><th>Sudah Terbiasa</th></tr></thead><tbody><?php $no=1;foreach($keys as $kolom=>$nama):$sudah=$terbiasa($kolom);?><tr><td><?=$no++?>.</td><td><?=$nama?></td><td class="kotak-centang"><?=$sudah?'':'✓'?></td><td class="kotak-centang"><?=$sudah?'✓':''?></td></tr><?php endforeach;?></tbody></table><div class="text-center mt-7">Menyetujui:</div><div class="grid grid-cols-2 mt-12 text-center font-serif"><div><p class="text-lg">Guru Kelas III</p><div class="h-24"></div><p class="text-lg font-bold underline underline-offset-4"><?=esc($namaGuruKelas)?></p></div><div><p class="text-lg">Orang Tua/Wali</p><div class="h-24"></div><p class="text-lg">_____________________</p></div></div><div class="mt-6 text-sm"><b>Keterangan:</b><br>Beri tanda checklist (✓) sesuai pilihan.<br>Belum terbiasa, jika anak belum melaksanakan 7 kebiasaan setiap hari.<br>Sudah terbiasa, jika anak sudah melaksanakan 7 kebiasaan setiap hari.</div></section>
<?php elseif($halaman==='admin' && (role('guru')||role('kepala_sekolah'))):$tanggalAdmin=$_GET['tanggal']??date('Y-m-d');$ambilJurnal=$db->prepare("SELECT j.*,p.nama,p.kelas FROM jurnal_harian j JOIN pengguna p ON p.id=j.id_murid WHERE j.tanggal=? ORDER BY p.nama");$ambilJurnal->execute([$tanggalAdmin]);$rows=$ambilJurnal->fetchAll(PDO::FETCH_ASSOC);$semuaMurid=$db->query("SELECT id,nama,kelas FROM pengguna WHERE peran='murid' AND nis IS NOT NULL ORDER BY nama")->fetchAll(PDO::FETCH_ASSOC);$sudahIds=array_flip(array_column($rows,'id_murid'));$siswaSudah=[];$siswaBelum=[];foreach($semuaMurid as $murid){if(isset($sudahIds[$murid['id']]))$siswaSudah[]=$murid;else $siswaBelum[]=$murid;}$elemen=['bangun_pagi'=>'Bangun Pagi','beribadah'=>'Beribadah','berolahraga'=>'Olahraga','makan_pagi'=>'Makan Sehat','gemar_belajar'=>'Belajar','bermasyarakat'=>'Bermasyarakat','tidur_cepat'=>'Tidur Cepat'];$nilaiElemen=[];foreach($elemen as $kolom=>$label)$nilaiElemen[$kolom]=count(array_filter($rows,fn($r)=>trim((string)($r[$kolom]??''))!==''));$maksRadar=max(1,count($semuaMurid));$titikRadar=[];$titikDalam=[];$i=0;foreach($nilaiElemen as $jumlah){$sudut=deg2rad(-90+$i*360/7);$rasio=$jumlah/$maksRadar;$titikRadar[]=round(110+88*$rasio*cos($sudut),1).','.round(110+88*$rasio*sin($sudut),1);$titikDalam[]=round(110+88*cos($sudut),1).','.round(110+88*sin($sudut),1);$i++;}?><div class="no-print flex flex-wrap justify-between gap-3 items-center mb-4"><div><h1 class="font-black text-xl text-sky-800">Dashboard Jurnal Harian Murid</h1><p class="text-sm text-slate-500">Pemantauan dan persetujuan jurnal harian.</p></div><form class="flex gap-2"><input type="hidden" name="halaman" value="admin"><input type="date" name="tanggal" value="<?=$tanggalAdmin?>" class="border rounded-lg p-2"><button class="bg-sky-600 text-white px-3 rounded-lg">Tampilkan</button></form></div><section class="no-print mb-5"><div class="grid sm:grid-cols-3 gap-3"><div class="rounded-2xl bg-emerald-50 border border-emerald-200 