dth="2"/></svg><div class="text-xs space-y-1"><?php foreach($elemen as $kolom=>$label):?><div><b><?=esc($label)?></b>: <?=$nilaiElemen[$kolom]?> murid</div><?php endforeach;?></div></div></div><div class="grid sm:grid-cols-2 gap-3"><div class="rounded-2xl bg-white border border-emerald-200 p-4"><h2 class="font-bold text-emerald-700">✓ Sudah mengerjakan (<?=count($siswaSudah)?>)</h2><ol class="text-sm mt-2 list-decimal list-inside"><?php foreach($siswaSudah as $m):?><li><?=esc($m['nama'])?></li><?php endforeach;if(!$siswaSudah):?><li class="list-none text-slate-400">Belum ada data.</li><?php endif;?></ol></div><div class="rounded-2xl bg-white border border-rose-200 p-4"><h2 class="font-bold text-rose-700">! Belum mengerjakan (<?=count($siswaBelum)?>)</h2><ol class="text-sm mt-2 list-decimal list-inside"><?php foreach($siswaBelum as $m):?><li><?=esc($m['nama'])?></li><?php endforeach;?></ol></div></div></div></section><h2 class="font-black text-lg text-sky-800 mb-3">Jurnal yang dikerjakan · <?=esc(tanggal_indonesia($tanggalAdmin))?></h2><div class="space-y-3"><?php foreach($rows as $r):?><div class="card bg-white rounded-xl p-4 border border-sky-100"><div class="flex justify-between"><b><?=esc($r['nama'])?> <span class="text-xs text-slate-400"><?=esc($r['kelas'])?></span></b><span class="text-xs"><?=esc($r['tanggal'])?></span></div><ol class="my-3 space-y-2 text-sm"><li class="rounded-lg bg-sky-50 p-2"><b>1. Bangun Pagi</b><br><span class="text-slate-600">Status: <?=esc($r['bangun_pagi'] ?: 'Belum diisi')?> · Jam bangun: <?=esc($r['jam_bangun'] ?: '-')?></span></li><li class="rounded-lg bg-violet-50 p-2"><b>2. Beribadah</b><br><span class="text-slate-600">Salat/ibadah dipilih: <?=esc($r['beribadah'] ?: 'Belum diisi')?><br>Ibadah lainnya: <?=esc($r['ibadah_lainnya'] ?: '-')?><br>Mengaji Al-Qur'an/Iqra halaman: <?=esc($r['mengaji_alquran'] ?: '-')?></span></li><li class="rounded-lg bg-emerald-50 p-2"><b>3. Berolahraga</b><br><span class="text-slate-600">Status: <?=esc($